var plId = Tama.Args.Get(args, "propertyLineId", 0L);
var tolMm = Tama.Args.Get(args, "tolMm", 1.0);
var targets = new List<XYZ>();
foreach (var o in (object[])args["targets"]) { var a = (object[])o; targets.Add(new XYZ(Convert.ToDouble(a[0])/0.3048, Convert.ToDouble(a[1])/0.3048, 0)); }
var pl = doc.ActiveProjectLocation;
var el = doc.GetElement(new ElementId((int)plId));
if (el == null) throw new Exception("Property line not found.");
var verts = new List<XYZ>();
foreach (var id in el.GetDependentElements(new ElementClassFilter(typeof(CurveElement)))) { var ce = doc.GetElement(id) as CurveElement; if (ce == null) continue; var c = ce.GeometryCurve; foreach (var p in new[]{c.GetEndPoint(0), c.GetEndPoint(1)}) if (!verts.Any(v => v.DistanceTo(new XYZ(p.X,p.Y,0)) < 0.003)) verts.Add(new XYZ(p.X,p.Y,0)); }
if (verts.Count != targets.Count) throw new Exception("Vertex count " + verts.Count + " != targets " + targets.Count);
Func<XYZ,XYZ> flat = q => new XYZ(q.X, q.Y, 0);
var inv0 = pl.GetTotalTransform().Inverse;
var pairs = targets.Select(t => new { t, v = verts.OrderBy(v => flat(inv0.OfPoint(v)).DistanceTo(t)).First() }).ToList();
double dE = pairs.Average(p => p.t.X - inv0.OfPoint(p.v).X);
double dN = pairs.Average(p => p.t.Y - inv0.OfPoint(p.v).Y);
var oldPos = pl.GetProjectPosition(XYZ.Zero);
pl.SetProjectPosition(XYZ.Zero, new ProjectPosition(oldPos.EastWest + dE, oldPos.NorthSouth + dN, oldPos.Elevation, oldPos.Angle));
doc.Regenerate();
var inv1 = pl.GetTotalTransform().Inverse;
var check = pairs.Select((p,i) => { var s = flat(inv1.OfPoint(p.v)); return new { pt = "P0"+(i+1), E = Math.Round(s.X*0.3048,4), N = Math.Round(s.Y*0.3048,4), errMm = Math.Round(s.DistanceTo(p.t)*304.8,2) }; }).ToList();
if (check.Any(c => c.errMm > tolMm)) throw new Exception("Corner error exceeds tolerance; rolled back.");
var np = pl.GetProjectPosition(XYZ.Zero);
return new { site = pl.Name, before = new { ew = Math.Round(oldPos.EastWest*0.3048,4), ns = Math.Round(oldPos.NorthSouth*0.3048,4), elev = Math.Round(oldPos.Elevation*0.3048,4), angle = Math.Round(oldPos.Angle*180/Math.PI,6) }, after = new { ew = Math.Round(np.EastWest*0.3048,4), ns = Math.Round(np.NorthSouth*0.3048,4), elev = Math.Round(np.Elevation*0.3048,4), angle = Math.Round(np.Angle*180/Math.PI,6) }, corners = check };
